--
-- Table structure for table `enquiry_table`
--

DROP TABLE IF EXISTS `enquiry_table`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `enquiry_table` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `EntryDateTime` datetime NOT NULL,
  `EntryUser` varchar(64) NOT NULL,
  `ClientContact` bigint(20) NOT NULL,
  `CSE` varchar(64) NOT NULL,
  `Attended` tinyint(1) NOT NULL,
  `Validity` tinyint(1) NOT NULL,
  `AttendedDateTime` datetime NOT NULL,
  `Source` varchar(32) NOT NULL,
  `ReasonForInvalidity` varchar(64) NOT NULL,
  `ClientName` varchar(60) NOT NULL,
  `ClientEmail` varchar(40) NOT NULL,
  `Gender` varchar(16) NOT NULL,
  `Age` int(11) NOT NULL,
  `DOB` date NOT NULL,
  `Address` varchar(512) NOT NULL,
  `ClientGST` varchar(15) NOT NULL,
  `ClientPAN` varchar(10) NOT NULL,
  `ConsultantId` int(11) NOT NULL,
  `ClientContactPerson` varchar(32) NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=MyISAM AUTO_INCREMENT=1415 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

